CREATE OR REPLACE FUNCTION fhirpg_genid()
RETURNS text AS $$
  select uuidv7()::text
$$ LANGUAGE sql;

CREATE TYPE _resource AS (
  id text,
  txid bigint,
  ts timestamptz,
  resource_type text,
  status resource_status,
  resource jsonb
);

CREATE OR REPLACE FUNCTION _fhirpg_to_resource(x _resource)
RETURNS jsonb AS $$
 select x.resource || jsonb_build_object(
  'resourceType', x.resource_type,
  'id', x.id,
  'meta', coalesce(x.resource->'meta', '{}'::jsonb) || jsonb_build_object(
    'lastUpdated', x.ts,
    'versionId', x.txid::text
  )
 );
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION fhirpg_create(resource jsonb, txid bigint)
RETURNS jsonb AS $FUNCTION$
DECLARE
  _sql text;
  rt text;
  tbl text;
  rid text;
  result jsonb;
BEGIN
    rt   := resource->>'resourceType';
    tbl  := lower(rt);
    rid  := coalesce(resource->>'id', fhirpg_genid());
    _sql := format($SQL$
      WITH upserted AS (
         INSERT INTO %I (id, ts, txid, status, resource)
         VALUES ($2, current_timestamp, $1, 'created', $3)
         ON CONFLICT (id)
         DO UPDATE SET
          txid = $1,
          ts = current_timestamp,
          status = 'recreated',
          resource = $3
         RETURNING
           old.id AS old_id, old.txid AS old_txid, old.ts AS old_ts,
           old.status AS old_status, old.resource AS old_resource,
           new.*
      ), archived AS (
        INSERT INTO %I (id, txid, ts, status, resource)
        SELECT old_id, old_txid, old_ts, old_status, old_resource
        FROM upserted
        WHERE old_id IS NOT NULL
        RETURNING *
      )

      select _fhirpg_to_resource(row(u.id, u.txid, u.ts, u.resource_type, u.status, u.resource)::_resource)
      from upserted u

      $SQL$,
      tbl, tbl || '_history');

  EXECUTE _sql
  USING txid, rid, jsonb_set(resource, '{id}', to_jsonb(rid::text), true)
  INTO result;

  return result;

END
$FUNCTION$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION fhirpg_create(resource jsonb)
RETURNS jsonb AS $FUNCTION$
   SELECT fhirpg_create(resource, nextval('transaction_id_seq'));
$FUNCTION$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION fhirpg_update(resource jsonb, txid bigint)
RETURNS jsonb AS $FUNCTION$
DECLARE
  _sql text ;
  rt text;
  tbl text;
  rid text;
  result jsonb;
BEGIN
    rt   := resource->>'resourceType';
    tbl  := lower(rt);
    rid  := resource->>'id';

    CASE WHEN (rid IS NULL) THEN
      RAISE EXCEPTION 'Resource does not have an id' USING HINT = 'Resource does not have an id';
    ELSE
    END CASE;

    _sql := format($SQL$
      WITH upserted AS (
         INSERT INTO %I (id, ts, txid, status, resource)
         VALUES ($2, current_timestamp, $1, 'created', $3)
         ON CONFLICT (id)
         DO UPDATE SET
          txid = $1,
          ts = current_timestamp,
          status = 'updated',
          resource = $3
         RETURNING
           old.id AS old_id, old.txid AS old_txid, old.ts AS old_ts,
           old.status AS old_status, old.resource AS old_resource,
           new.*
      ), archived AS (
        INSERT INTO %I (id, txid, ts, status, resource)
        SELECT old_id, old_txid, old_ts, old_status, old_resource
        FROM upserted
        WHERE old_id IS NOT NULL
        RETURNING *
      )

      select _fhirpg_to_resource(row(u.id, u.txid, u.ts, u.resource_type, u.status, u.resource)::_resource)
      from upserted u

      $SQL$,
      tbl, tbl || '_history');

  EXECUTE _sql
  USING txid, rid, (resource - 'id')
  INTO result;

  return result;

END
$FUNCTION$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION fhirpg_update(resource jsonb)
RETURNS jsonb AS $FUNCTION$
   SELECT fhirpg_update(resource, nextval('transaction_id_seq'));
$FUNCTION$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION fhirpg_read(resource_type text, id text)
RETURNS jsonb AS $FUNCTION$
DECLARE
  _sql text;
  result jsonb;
BEGIN
  _sql := format($SQL$
    SELECT _fhirpg_to_resource(row(r.*)::_resource) FROM %I r WHERE r.id = $1
  $SQL$,
  lower(resource_type)
  );

  EXECUTE _sql USING id INTO result;

  return result;
END
$FUNCTION$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION fhirpg_delete(resource_type text, id text, txid bigint)
RETURNS jsonb AS $FUNCTION$
DECLARE
  _sql text;
  rt text;
  tbl text;
  rid text;
  result jsonb;
BEGIN
    rt   := resource_type;
    tbl  := lower(rt);
    rid  := id;
    _sql := format($SQL$
      WITH dropped AS (
         DELETE FROM %I WHERE id = $2
         RETURNING old.id, old.txid, old.ts, old.status, old.resource
      ), archived AS (
        INSERT INTO %I (id, txid, ts, status, resource)
        SELECT id, $1, current_timestamp, 'deleted', resource
        FROM dropped
        RETURNING *
      )
      select _fhirpg_to_resource(row(d.id, d.txid, d.ts, $3, d.status, d.resource)::_resource)
      from dropped d

      $SQL$,
      tbl, tbl || '_history');

  EXECUTE _sql
  USING txid, rid, rt
  INTO result;

  return result;

END
$FUNCTION$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION fhirpg_delete(resource_type text, id text)
RETURNS jsonb AS $FUNCTION$
   SELECT fhirpg_delete(resource_type, id, nextval('transaction_id_seq'));
$FUNCTION$ LANGUAGE sql;
